Cred OA | 2025 | string swap
* Recently, Online assessment of CRED, a medium but mind-boggling question appeared.

![image.png](https://assets.leetcode.com/users/images/bc160c5b-0d65-410b-bb12-0fdb34ad4a01_1755057447.970606.png)



> you have to swap all character of b1 with all character of b2, in such a way that , it will make string smallest.

```
#include <bits/stdc++.h>
using namespace std;

string minimizeByCharSwaps(string s) {
    int n = s.size();
    vector<bool> used(26, false);
    unordered_map<char, char> mp;

    for (int i = 0; i < n; i++) {
        char ch = s[i];
        int idx = ch - 'a';
        if (used[idx]) continue; // already swapped

        // find smallest possible swap candidate
        char smallest = ch;
        for (int j = n - 1; j > i; j--) { // look to the right
            if (s[j] < smallest && !used[s[j] - 'a']) {
                smallest = s[j];
            }
        }

        if (smallest < ch) {
            // register swap mapping
            mp[ch] = smallest;
            mp[smallest] = ch;
            used[idx] = true;
            used[smallest - 'a'] = true;
        }
    }

    // apply swaps
    for (int i = 0; i < n; i++) {
        if (mp.count(s[i])) {
            s[i] = mp[s[i]];
        }
    }

    return s;
}

int main() {
    string s;
    cin >> s;
    cout << minimizeByCharSwaps(s) << "\n";
    return 0;
}


